//! ProtoWallet's four signature/HMAC validators, recorded from ts-stack@edf6e03.
//! Every refusal test was red on 326b0836; the fixture is generated by
//! support/wallet_proto_args_415.mjs, including the first-error witnesses.
#![cfg(feature = "wallet")]
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use bsv_rs::primitives::PrivateKey;
use bsv_rs::wallet::{
    Counterparty, CreateHmacArgs, CreateSignatureArgs, ProtoWallet, Protocol, SecurityLevel,
    VerifyHmacArgs, VerifySignatureArgs,
};
use bsv_rs::{Error, Result, WalletRefusalClass};
use serde::Deserialize;
use serde_json::{json, Value};

const VECTOR: &str = include_str!("vectors/wallet_proto_args_415.json");

#[derive(Deserialize)]
#[serde(untagged)]
enum Bytes {
    Literal(Vec<u8>),
    Repeated { length: usize, byte: u8 },
}

impl Bytes {
    fn bytes(&self) -> Vec<u8> {
        match self {
            Self::Literal(bytes) => bytes.clone(),
            Self::Repeated { length, byte } => vec![*byte; *length],
        }
    }
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Request {
    #[serde(rename = "protocolID")]
    protocol: (u8, String),
    #[serde(rename = "keyID")]
    key_id: String,
    counterparty: String,
    data: Option<Bytes>,
    signature: Option<Bytes>,
    hmac: Option<[u8; 32]>,
    hash_to_directly_sign: Option<[u8; 32]>,
    hash_to_directly_verify: Option<[u8; 32]>,
    privileged: Option<bool>,
    privileged_reason: Option<String>,
    seek_permission: Option<bool>,
    for_self: Option<bool>,
}

macro_rules! args {
    ($kind:ident, $r:ident, $($field:ident: $value:expr),* $(,)?) => {
        $kind {
            protocol_id: Protocol::new(SecurityLevel::from_u8($r.protocol.0).unwrap(), &$r.protocol.1),
            key_id: $r.key_id.clone(),
            counterparty: Some(match $r.counterparty.as_str() {
                "self" => Counterparty::Self_,
                "anyone" => Counterparty::Anyone,
                other => Counterparty::Other(bsv_rs::PublicKey::from_hex(other).unwrap()),
            }),
            privileged: $r.privileged,
            privileged_reason: $r.privileged_reason.clone(),
            seek_permission: $r.seek_permission,
            $($field: $value,)*
        }
    };
}

fn invoke(case: &Value) -> Result<Value> {
    let r: Request = serde_json::from_value(case["args"].clone()).unwrap();
    let wallet = ProtoWallet::new(Some(PrivateKey::from_hex(&format!("{:064x}", 42)).unwrap()));
    let data = r.data.as_ref().map(Bytes::bytes);
    match case["method"].as_str().unwrap() {
        "createSignature" => wallet
            .create_signature(args!(CreateSignatureArgs, r, data: data,
                hash_to_directly_sign: r.hash_to_directly_sign))
            .map(|r| json!({ "signature": r.signature })),
        "verifySignature" => wallet
            .verify_signature(args!(VerifySignatureArgs, r, data: data,
                hash_to_directly_verify: r.hash_to_directly_verify,
                signature: r.signature.as_ref().unwrap().bytes(), for_self: r.for_self))
            .map(|r| json!({ "valid": r.valid })),
        "createHmac" => wallet
            .create_hmac(args!(CreateHmacArgs, r, data: data.unwrap_or_default()))
            .map(|r| json!({ "hmac": r.hmac })),
        "verifyHmac" => wallet
            .verify_hmac(
                args!(VerifyHmacArgs, r, data: data.unwrap_or_default(), hmac: r.hmac.unwrap()),
            )
            .map(|r| json!({ "valid": r.valid })),
        other => panic!("unknown method {other}"),
    }
}

fn assert_case(case: &Value) {
    let expected = &case["expected"];
    let result = invoke(case);
    if let Some(words) = expected["error"].as_str() {
        let error = if expected["code"] == 6 {
            Error::WalletRefusal {
                class: WalletRefusalClass::InvalidParameter,
                message: words.into(),
            }
        } else {
            Error::WalletError(words.into())
        };
        assert_eq!(result, Err(error), "{} / {}", case["method"], case["name"]);
    } else {
        assert_eq!(
            result.unwrap(),
            expected["result"],
            "{} / {}",
            case["method"],
            case["name"]
        );
    }
}

fn cases() -> Vec<Value> {
    let fixture: Value = serde_json::from_str(VECTOR).unwrap();
    let recorded = fixture["cases"].as_array().unwrap();
    let unrepresentable = recorded
        .iter()
        .filter(|case| case.get("unrepresentable").is_some())
        .count();
    assert_eq!(
        unrepresentable, 85,
        "the recorded type-enforced case count changed"
    );
    let replayable: Vec<_> = recorded
        .iter()
        .filter(|case| case.get("unrepresentable").is_none())
        .cloned()
        .collect();
    assert_eq!(
        replayable.len(),
        117,
        "the recorded replayable case count changed"
    );
    replayable
}

fn assert_refusal(words: &str) {
    let cases: Vec<_> = cases()
        .into_iter()
        .filter(|case| case["expected"]["error"] == words)
        .collect();
    assert!(!cases.is_empty(), "missing recorded refusal {words}");
    for case in cases {
        assert_case(&case);
    }
}

macro_rules! refusal {
    ($name:ident, $words:literal) => {
        #[test]
        fn $name() {
            assert_refusal($words);
        }
    };
}

refusal!(
    a_short_protocol_uses_the_validator_words,
    "The protocolID[1] parameter must be at least 5 length."
);
refusal!(
    a_long_protocol_uses_the_validator_words_and_utf8_bytes,
    "The protocolID[1] parameter must be no more than 400 length."
);
refusal!(
    an_empty_key_id_uses_the_validator_words,
    "The keyID parameter must be at least 1 length."
);
refusal!(
    a_long_key_id_uses_the_validator_words_and_utf8_bytes,
    "The keyID parameter must be no more than 800 length."
);
refusal!(
    a_short_privileged_reason_is_refused_even_without_privilege,
    "The privilegedReason parameter must be at least 5 length."
);
refusal!(
    a_long_privileged_reason_uses_utf8_bytes,
    "The privilegedReason parameter must be no more than 50 length."
);
refusal!(
    privileged_access_requires_a_reason_before_processing_data,
    "The privilegedReason parameter must be a value when 'privileged' is true"
);
refusal!(
    signing_requires_exactly_one_data_or_hash_value,
    "The data, hashToDirectlySign parameter must be exactly one value"
);
refusal!(
    verification_requires_exactly_one_data_or_hash_value_before_der,
    "The data, hashToDirectlyVerify parameter must be exactly one value"
);
refusal!(
    oversized_data_is_refused_before_hashing,
    "The data parameter must be at most 268435456 bytes"
);
refusal!(
    oversized_signatures_use_the_validator_words_before_der,
    "The signature parameter must be at most 72 bytes"
);
refusal!(
    noncanonical_signatures_use_the_validator_words_before_der_or_derivation,
    "The signature parameter must be a canonical DER-encoded ECDSA signature"
);

#[test]
fn valid_boundaries_and_cryptographic_misses_keep_the_reference_results() {
    for case in cases().iter().filter(|case| case["expected"]["code"] != 6) {
        assert_case(case);
    }
}

#[test]
fn multiple_invalid_arguments_follow_the_reference_validation_order() {
    for case in cases()
        .iter()
        .filter(|case| case["name"].as_str().unwrap().starts_with("order_"))
    {
        assert_case(case);
    }
}
